-- Loch Modan: creature abilities
-- Most of the zone's creatures (Stonesplinter, Tunnel Rat, Mosshide, Twilight, the wildlife and the Thelsamar mountaineers) had no
-- AI or ran classic rows. Loch Modan is the Cataclysm revamp, so port their abilities from the Cataclysm data, keeping the scripts
-- already in place. The Twilight Landshaper, which no reference scripts, casts its sniffed spell (creature_template spell1-8).

SET @ENTRIES := '1161,1162,1164,1165,1167,1172,1173,1174,1177,1186,1197,1225,1276,1277,1278,1279,1280,1281,1282,1283,1329,1331,1332,1336,1337,1338,1398,1399,1425,1693,2105,2476,2506,2507,2508,2509,2510,2511,2512,2513,2514,2515,2516,2517,2518,13076,14266,14267,14268,33456,42230,44161,44162,44163,44176,44184,44188,44197,44198,44292,44576,44616,44620,44626,44627,44628,44635,44638,44729,44760,44771,45336,45369,45380,45384,45398,45401,45402,45404,49784';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);

-- Creatures without reference data: their sniffed creature_template spell1-8
SET @ENTRIES := '44724';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
